const banner=document.createElement('div');banner.id='linkedBanner';banner.hidden=true;banner.innerHTML='<span id="linkedBannerLabel"></span><button id="showLinked">연결 데이터 보기 →</button>';document.querySelector('.titlebar').after(banner);
